import heapq


def letter_order(words: list[str]) -> str:
    after = {ch: set() for word in words for ch in word}
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                after[x].add(y)              # a set: a repeated pair counts once
                break
        else:
            if len(a) > len(b):
                return ""                    # a word placed before its own prefix
    indeg = {ch: sum(ch in nexts for nexts in after.values()) for ch in after}
    ready = [ch for ch in after if indeg[ch] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        ch = heapq.heappop(ready)            # smallest ready letter first
        order.append(ch)
        for nxt in after[ch]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)
    return "".join(order) if len(order) == len(after) else ""
